import { action, observable, makeObservable } from "mobx";
import { generate, getRgbStr } from '@arco-design/color';

const cacheKey = "local-storage-theme";

class Theme {
    // 当前平台主题（亮色、暗色）
    theme: "dark" | "light" = "light";
    // 切换当前主题（亮色、暗色）
    setTheme = (theme: "dark" | "light") => {
        if(this.theme == theme) return;
        this.theme = theme;
        localStorage.setItem(cacheKey, theme);
        if(this.themeColor){
            // 主题色需要更新
            this.setThemeColor(this.themeColor); 
        }
        switch(theme){
            case "dark":
                // 设置为暗黑主题
                document.body.setAttribute('arco-theme', 'dark');
            break;
            case "light":
                document.body.removeAttribute('arco-theme');
            break;
        }
    };


    // 当前平台主题，主题色
    themeColor: string = "";
    setThemeColor = (color) => {
        if(color == this.themeColor) return;
        if(color){
            // 切换当前主题色
            const list = this.getColorList(color);
            list.forEach((rgb, index) => {
                document.body.style.setProperty(
                    `--arcoblue-${index + 1}`,
                    rgb
                ); 
            });
        }else {
            // 删除之前添加的主题色（恢复到默认主题色）
            new Array(10).fill(0).forEach((_,index) => {
                document.body.style.removeProperty(`--arcoblue-${index + 1}`,)
            })
        }
        this.themeColor = color;
    };



    /**
     * 获取梯级颜色列表
     */
    getColorList = (color, dark?: string) => {
        const newList = generate(color, {
            list: true,
            dark: (dark || this.theme) === 'dark',
        });
        return newList.map((l, index) => {
            const rgbStr = getRgbStr(l);
            return rgbStr;
        });
    }


    constructor() {
        makeObservable(this, {
            theme: observable,
            setTheme: action,
            themeColor: observable,
            setThemeColor: action
        });

        // const theme = localStorage.getItem(cacheKey);
        // if(theme){
        //     this.setTheme(theme as any);
        // }
    }
}

export default new Theme();