import { languageType } from "@/types/language";
import _ from 'lodash';
import app from "./app";
import languaStore from "@code/locales/index";
import zhCN from "@code/locales/lang/zh-CN";
import zhTW from "@code/locales/lang/zh-TW";
import zhHK from "@code/locales/lang/zh-HK";
import enUS from "@code/locales/lang/en-US";
import deDE from "@code/locales/lang/de-DE";
import frFR from "@code/locales/lang/fr-FR";
import ruRU from "@code/locales/lang/ru-RU";
import jaJP from "@code/locales/lang/ja-JP";
import koKR from "@code/locales/lang/ko-KR";
import ajax from "@/utils/ajax";




/**
 * 全局页面数据
 */
class Language {

    /**
     * 所有多语言
     */
    list: any[] = [];

    /**
     * 多语言配置
     */
    options: Array<{ value: languageType, label: string }> = [
        { value: 'zh-CN', label: '中文' },
        { value: 'en-US', label: 'English' },
        { value: 'zh-HK', label: '繁體中文（香港）' },
        { value: 'zh-TW', label: '繁體中文（臺灣）' },
        { value: 'de-DE', label: '德语(Deutsch)' },
        { value: 'ru-RU', label: "俄语(Русский язык)" },
        { value: 'ja-JP', label: '日本語' },
        { value: 'ko-KR', label: '韩语(한국어)' },
        { value: 'fr-FR', label: '法语(Français)' },
    ]

    getLanguageData(key: languageType){
        switch(key){
            case "zh-CN": return zhCN;
            case 'en-US': return enUS;
            case 'zh-HK': return zhHK;
            case 'zh-TW': return zhTW;
            case 'de-DE': return deDE;
            case 'ru-RU': return ruRU;
            case 'ja-JP': return jaJP;
            case 'ko-KR': return koKR;
            case 'fr-FR': return frFR;
        }
    }


    /**
     * app Options
     */
    get AppOptions(){
        return this.options.filter((o) => app.extraInfo.languageKeys.includes(o.value)).map((o) => {
            return { ...o, data: this.getLanguageData(o.value) }
        })
    }

    /**
     * 重置多语言
     */
    initLanguage = async (list: any[]) => {
        const objs: any = {};
        const keys = ['zhCN', 'zhTW', 'zhHK', 'enUS', 'deDE', 'frFR', 'ruRU', 'jaJP', 'koKR'];
        for (const key of keys) {
            objs[key] = {};
        }
        for (const item of list) {
            for (const key of keys) {
                objs[key][item.languekey] = item[key];
            }
        }
        Object.assign(zhCN, objs.zhCN)
        Object.assign(zhTW, objs.zhTW)
        Object.assign(zhHK, objs.zhHK)
        Object.assign(enUS, objs.enUS)
        Object.assign(deDE, objs.deDE)
        Object.assign(frFR, objs.frFR)
        Object.assign(ruRU, objs.ruRU)
        Object.assign(jaJP, objs.jaJP)
        Object.assign(koKR, objs.koKR)
        await languaStore.changeLang(languaStore.lang)

        for (const key in objs.zhCN) {
            const zh = objs.zhCN[key];
            const en = objs.enUS[key];
            this.list.push({
                key,
                zhCN: zh,
                enUS: en,
                input: `${key}-${zh}-${en}`
            })
        }
    }


    /**
     * 加载App多语言
     */
    reloadApp = async (keys: string[]) => {
        await ajax.post('/apijson/get', {
            ...(
                keys.length? {
                    "LanguageAll[]": {
                        "count": 0,
                        "LanguageAll": {
                            "languekey{}": keys,
                            "@column": "languekey,zhCN,zhTW,zhHK,enUS,deDE,frFR,ruRU,jaJP,koKR"
                        }
                    },
                } : {}
            ),
            "Language[]": {
                "count": 0,
                "Language": {

                }
            }
        }).then((res) => {
            const { LanguageAll = [], Language = [] } = res;
            const langList = [...LanguageAll, ...Language]
            return this.initLanguage(langList);
        })
    }


    /**
     * 加载插件多语言
     */
    reloadPlugin = async () => {
        return ajax.post('/apijson/gets', {
            "LanguageAllRelevance[]": {
                "count": 0,
                "join": "&/LanguageAll",
                "LanguageAllRelevance": {
                    "@column": "id,languekey",
                },
                "LanguageAll": {
                    "languekey@": "/LanguageAllRelevance/languekey",
                    "@column": "zhCN,zhTW,zhHK,enUS,deDE,frFR,ruRU,jaJP,koKR"
                }
            }
        }).then((res) => {
            const list = res.LanguageAllRelevance;
            return this.initLanguage(list)
        })
    }

    /**
     * 加载项目多语言
     */
    reloadProject = async () => {
        return ajax.post('/apijson/gets', {
            "LanguageAllRelevance[]": {
                "count": 0,
                "join": "&/LanguageAll",
                "LanguageAllRelevance": {
                    "@column": "id,languekey",
                },
                "LanguageAll": {
                    "languekey@": "/LanguageAllRelevance/languekey",
                    "@column": "zhCN,zhTW,zhHK,enUS,deDE,frFR,ruRU,jaJP,koKR"
                }
            }
        }).then((res) => {
            const list = res.LanguageAllRelevance;
            return this.initLanguage(list)
        })
    }
}

export default new Language();