import { observable, action, computed, makeObservable } from 'mobx';


class Store {
    // 默认展示层级 4/6 6/4 8/3 12/2
    colSpan = 8;

    constructor() {
        makeObservable(this, {
            colSpan: observable,
            columnSpan: computed,
            isAll: observable,
            setIsAll: action
        });

        makeObservable(this);
    }

    // 列表层级数量
    get columnSpan() {
        return Math.floor(24/this.colSpan);
    }

    isAll = false;

    setIsAll = (bool) => {
        this.isAll = bool;
    };
}

export default Store;