import config from "mainConfig";

/**
 * 用户获取文件目录地址, 目录统一管理
 * build 为构建后的版本
 */
class Dir {

    
    // 返回当前web 基础构建包
    getWeb(){
        return `${config.CDNURL}/deploy/web/${config.webBuildHashVersion}.zip`
    }

    // 获取当前web code 代码构建包
    getWebCode(){
        return `${config.CDNURL}/deploy/web_code/${config.webCodeVersion}.zip`
    }

    /**
     * 根据版本号获取项目应用目录地址
     */
    app = {
        // 路径获取
        getTestZipPath: (appId: string, version: string) => {
            return `app/${appId}/test/${version}.zip`
        },
        getProdZipPath: (appId: string, version: string) => {
            return `app/${appId}/prod/${version}.zip`
        },
        // 构建版本文件地址
        getTestZipUrl: (appId: string, version: string) => {
            return `${config.CDNURL}/${config.uploadFiel}/${this.app.getTestZipPath(appId, version)}`
        },
        // 获取build版本文件地址
        getProdZipUrl: (appId: string, version: string) => {
            return `${config.CDNURL}/${config.uploadFiel}/${this.app.getProdZipPath(appId, version)}`
        },
    }

    /**
     * 根据版本号获取项目目录地址
     */
    project = {
        // 路径获取
        getPath: (projectId: string, version: string) => {
            return `project/${projectId}/code/${version}.js`
        },
        getBuildPath: (projectId: string, version: string) => {
            return `project/${projectId}/build/${version}.js`
        },
        // 构建版本文件地址
        get: (projectId: string, version: string) => {
            return `${config.CDNURL}/${config.uploadFiel}/${this.project.getPath(projectId, version)}`
        },
        // 获取build版本文件地址
        getBuild: (projectId: string, version: string) => {
            return `${config.CDNURL}/${config.uploadFiel}/${this.project.getBuildPath(projectId, version)}`
        },
    }

    /**
     * 根据版本号获取插件目录地址
     */
    plugin = {
        // 路径获取
        getPath: (pluginId: string, version: string) => {
            return `plugin/${pluginId}/code/${version}.js`
        },
        getBuildPath: (pluginId: string, version: string) => {
            return `plugin/${pluginId}/build/${version}.js`
        },
        // 构建版本文件地址
        get: (pluginId: string, version: string) => {
            return `${config.CDNURL}/${config.uploadFiel}/${this.plugin.getPath(pluginId, version)}`
        },
        // 获取build版本文件地址
        getBuild: (pluginId: string, version: string) => {
            return `${config.CDNURL}/${config.uploadFiel}/${this.plugin.getBuildPath(pluginId, version)}`
        }
    }
}

export default new Dir();