import { history } from './history';
import qs from 'query-string';


// 判断是否为函数类型
function isFunction(val): boolean {
    return typeof val === 'function';
}

// 判断是否为promise 类型
function isPromise(val): boolean {
    return typeof val === 'object' && isFunction(val.then) && isFunction(val.catch) && isFunction(val.finally);
}


/**
 * 获取url中所有参数
 * @defaultValue object 默认参数
 */
function getAllQueryParam(defaultValue:Record<string, any> = {} ): Record<string, any>{
  const url = location.href;
  if (!url || url.indexOf('?') === -1) return defaultValue;
  // 解析查询参数
  const parsed = qs.parseUrl(url).query;
  return { ...defaultValue, ...parsed }
}


export default {
    history,
    isPromise,
    getAllQueryParam,
}
