import React, { useMemo } from "react";
import { Form } from "@arco-design/web-react";
import FieldRender from './Field';
import utils from "utils";
import { FormItem } from "../../interface";


interface FormItemRenderProps {
    render: FormItem['render']
    valueType: FormItem['valueType']
    fieldProps: FormItem['fieldProps']
    show: FormItem['show']
    field: FormItem['field']
    formItemProps: FormItem['formItemProps']
}

const FormItemRender = ({
    render: Element,
    valueType,
    fieldProps,
    show,
    field,
    formItemProps,
}: FormItemRenderProps) => {

    const { form, disabled } = Form.useFormContext();

    const rules = useMemo(() => {
        if (formItemProps.validator) {
            return [
                ...formItemProps.rules,
                {
                    trigger: formItemProps.validateTrigger,
                    validator: async (value, callback) => {
                        const formData = form.getFields();
                        const result = formItemProps.validator(formData, callback);
                        if (utils.isPromise(result)) await result;
                    }
                }
            ]
        }
        return formItemProps.rules;
    }, [formItemProps.rules])

    if (show === false) return null;


    if (typeof show == 'function' || typeof fieldProps == 'function'){
        return (
            <Form.Item
                key={field}
                noStyle
                shouldUpdate={formItemProps.shouldUpdate || true}
            >
                {() => {
                    const values = form.getFields();
                    // 判断是否需要隐藏props
                    if(typeof show == 'function' && !show(values)){
                        return null;
                    }
                    const fieldParams = typeof fieldProps == 'function'? fieldProps(values) : fieldProps;
                    return (
                        <Form.Item field={field} {...formItemProps} rules={rules} >
                            {Element? (
                                <Element
                                    form={form}
                                    Field={fieldParams}
                                    {...fieldProps}
                                />
                            ) : (
                                <FieldRender
                                    valueType={valueType}
                                    fieldProps={fieldParams}
                                />
                            )}
                        </Form.Item>
                    )
                }}
            </Form.Item>
        )
    }else {
        return (
            <Form.Item field={field} {...formItemProps} rules={rules} >
                {Element? (
                        <Element
                            form={form}
                            Field={FieldRender}
                            {...fieldProps}
                        />
                ) : (
                    <FieldRender
                        valueType={valueType}
                        fieldProps={fieldProps}
                    />
                )}
            </Form.Item>
        )
    }
}


export default FormItemRender;