/**
 * @name 层级数据扁平化处理
 * @param tree 
 * @returns 
 */
export function flattenTree(tree: any[]) {
    const result = [];
    
    function flatten(node) {
      result.push(node);
      
      if (node.children && node.children.length > 0) {
        node.children.forEach(flatten);
      }
    }
    
    tree.forEach(flatten);
    
    return result;
}