import PageRouteContext from '../context';
import React, { memo, useMemo } from "react";
import { IRoute } from "@/types/route";


interface PageRouteLayoutProps {
    route: IRoute;
}

const PageRouteLayout = memo(({ route }: PageRouteLayoutProps) => {



    const Element = route.component;

    const value = useMemo(() => {
        return { route };
    },[])



    return (
        <PageRouteContext.Provider value={value}>
            <Element />
        </PageRouteContext.Provider>
    )
})


export default PageRouteLayout;