import utils from "utils";
import ajax from "ajax";
import { ParamsProps, TreeDatasProps } from "./interface";
import { adminRoutes } from "../../../routes";

/**
 * @name 返回多级别数据
 */
export function convertToTree(data, key: string = 'id', parentKey: string = 'parentId'): any[] {
  const map = {}; // 使用普通对象代替 Map
  const roots = [];

  // 将每个节点存储到 map 中
  for (let i = 0; i < data.length; i++) {
    const { [key]: id } = data[i];
    const children = [];
    map[id] = { ...data[i], children }; // 将节点存储到 map 中
  }

  // 遍历数据，构建树形结构
  for (let i = 0; i < data.length; i++) {
    const { [key]: id, [parentKey]: uid } = data[i];
    const parent = map[uid]; // 获取父节点对象
    if (parent) {
      parent.children.push(map[id]); // 将节点添加到父节点的 children 数组中
    } else {
      roots.push(map[id]); // 没有父节点，将节点添加到根节点数组中
    }
  }

  return roots; // 返回根节点数组
}



const getArctype = (type: number) => {
  return {
    find: ({ params = {} }: ParamsProps) => {
      return ajax.post('/apijson/get', {
          "Arctype[]":{
            "count": 0,
            "Arctype":{
              ...params,
              "ishidden": 1,
              "channeltype": type,
              "@order":"sortrank+",
              "@column":"id,typename,sortrank,reid"
            }
          },
        }).then((res) => {
          return convertToTree(res.Arctype, "id", "reid");
        })
    },
    fieldNames: {
      key: 'id',
      title: 'typename',
    }
  }
}

export default {
  "Arctype1": getArctype(1),
  "Arctype2": getArctype(2),
  "Arctype3": getArctype(3),
  "Arctype4": getArctype(4),
  "Arctype5": getArctype(5),
  "Arctype6": getArctype(6),
  "Arctype7": getArctype(7),
  "Arctype8": getArctype(8),
  'menuRoles': {
    fieldNames: {
      key: 'authority',
      title: 'name',
    },
    find: async ({ }: ParamsProps) => {
      const loop = (list: any[]) => {
        return list.filter((o) => {
          return o.authority
        }).map((o) => {
          return {
            ...o,
            icon: undefined,
            children: loop(o.children)
          }
        })
      }
      return loop(adminRoutes);
    },
  },
} as {
    [key in string]: TreeDatasProps
};
